"""Gold ingredient library: which Valio products are an acceptable buy for each ingredient.

A product is acceptable when its category code is in `cats` AND (if given) its
lower-cased English+Finnish name contains one of `any` AND none of `none`.
Category codes come from Valio's data (names are not published; groups were
identified by inspecting members, see scripts/cat_peek.py).
"""
I = {}
def ing(iid, cats, any_=(), none=(), note=""):
    I[iid] = {"id": iid, "cats": list(cats), "any": list(any_), "none": list(none), "note": note}

